rules.message:
AMP support has been removed in Next.js 16. Remove imports from `next/amp`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
import { useAmp } from 'next/amp';
export const config = { amp: true };

// ✅ AFTER
// Remove AMP exports and build responsive standard HTML/CSS
export default function Page() { return <div>Standard Page</div>; }
```
</details>

`unstable_cache` is deprecated in Next.js 16 in favor of `'use cache'`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
import { unstable_cache } from 'next/cache';
const getData = unstable_cache(async () => fetchUser(id), ['users']);

// ✅ AFTER
async function getData(id: string) {
  'use cache';
  return fetchUser(id);
}
```
</details>

